// Extraer URL del video viral final de JSON2Video
const json2videoResponse = $input.first().json;
const staticData = $getWorkflowStaticData('global');

// Extraer URL del video final
const finalVideoUrl = json2videoResponse.movie?.url || json2videoResponse.url;

if (!finalVideoUrl) {
  throw new Error('JSON2Video no retorno URL del video final. Status: ' + (json2videoResponse.movie?.status || json2videoResponse.status || 'unknown'));
}

console.log('=== VIDEO VIRAL FINAL ===');
console.log('Video viral URL: ' + finalVideoUrl);

// Obtener datos del static data
const idea = staticData.idea || '';
const audioUrl = staticData.audio_url || '';
const escenas = staticData.escenas || [];

console.log('Datos del workflow:');
console.log('- Idea: ' + (idea ? idea.substring(0, 50) + '...' : 'VACIO'));
console.log('- Audio URL: ' + (audioUrl ? 'OK' : 'VACIO'));
console.log('- Escenas: ' + escenas.length);

return [{
  json: {
    // Datos del video viral final
    video_viral_url: finalVideoUrl,
    json2video_duration: json2videoResponse.movie?.duration || 0,
    json2video_size: json2videoResponse.movie?.size || 0,
    rendering_time: json2videoResponse.movie?.rendering_time || 0,
    json2video_status: json2videoResponse.movie?.status || json2videoResponse.status || 'completed',

    // Datos originales del workflow
    idea: idea,
    audio_url: audioUrl,
    escenas_count: escenas.length,

    // Para compatibilidad con nodos siguientes
    video_url: finalVideoUrl,
    webViewLink: finalVideoUrl
  }
}];

// CONSTRUIR PAYLOAD JSON2VIDEO - COBERTURA COMPLETA

const firstItem = $input.first().json;
if (!firstItem.videos) {
  return [];
}

const audioData = $('Subir archivo a tmpfiles').first().json;
const audioUrl = audioData.data.url.replace('tmpfiles.org/', 'tmpfiles.org/dl/');

const pexelsResults = $input.all().map(item => item.json);
const numBrolls = pexelsResults.length;

const duracionTotal = 45; // Un poco más para asegurar cobertura
const duracionPorEscena = Math.floor(duracionTotal / numBrolls);

const elements = [];

// AUDIO
elements.push({
  type: "audio",
  src: audioUrl,
  start: 0,
  duration: -1,
  volume: 1
});

// B-ROLLS
pexelsResults.forEach((pexelsData, idx) => {
  const startTime = idx * duracionPorEscena;
  const esUltimo = idx === numBrolls - 1;

  const videos = pexelsData.videos || [];
  if (videos.length === 0) return;

  const video = videos[0];
  const videoFiles = video.video_files || [];
  if (videoFiles.length === 0) return;

  let bestFile = videoFiles.find(f => f.width === 1080 && f.height === 1920)
    || videoFiles.find(f => f.height > f.width && f.quality === 'hd')
    || videoFiles.find(f => f.height > f.width)
    || videoFiles[0];

  if (!bestFile?.link) return;

  elements.push({
    type: "video",
    src: bestFile.link,
    start: startTime,
    duration: esUltimo ? -2 : duracionPorEscena, // -2 = hasta el final del scene/movie
    "z-index": 0,
    resize: "cover",
    muted: true,
    loop: -1
  });

  console.log('B-roll ' + (idx+1) + ': ' + startTime + 's - ' + (esUltimo ? 'FIN' : (startTime + duracionPorEscena) + 's'));
});

// SUBTITULOS
elements.push({
  type: "subtitles",
  language: "es",
  settings: {
    style: "boxed-word",
    position: "bottom-center",
    "font-family": "Montserrat",
    "font-size": 60,
    "font-weight": "700",
    "line-color": "#FFFFFF",
    "word-color": "#FFFF00",
    "box-color": "#000000",
    "max-words-per-line": 4
  }
});

const payload = {
  resolution: "custom",
  width: 1080,
  height: 1920,
  quality: "high",
  fps: 30,
  scenes: [{
    elements: elements,
    duration: -1
  }]
};

return [{ json: { json2video_payload: payload } }];

