// Obtener escenas del AI Agent
const escenas = $('AI Agent').first().json.output.escenas;

// Función para convertir "MM:SS" a segundos
function timeToSeconds(timeStr) {
  const [min, sec] = timeStr.split(':').map(Number);
  return min * 60 + sec;
}

// Crear un item por cada escena
return escenas.map(escena => ({
  json: {
    numero: escena.numero,
    inicio: timeToSeconds(escena.inicio),
    fin: timeToSeconds(escena.fin),
    duracion: timeToSeconds(escena.fin) - timeToSeconds(escena.inicio),
    tema: escena.tema,
    search_query: escena.keywords.slice(0, 2).join(' '),
    keywords: escena.keywords
  }
}));

// Extraer el texto con el JSON
const rawText = $input.first().json.output[0].content[0].text;

// Extraer JSON del bloque de código markdown
const jsonMatch = rawText.match(/```json\n([\s\S]*?)\n```/);

if (!jsonMatch) {
  throw new Error('No se encontró JSON en la respuesta');
}

const copies = JSON.parse(jsonMatch[1]);

return [{
  json: {
    instagram: copies.instagram,
    tiktok: copies.tiktok,
    youtube_titulo: copies.youtube_titulo,
    youtube_descripcion: copies.youtube_descripcion,
    twitter: copies.twitter
  }
}];
